class TransientError(Exception):
    """A retryable integration failure."""


class PermanentError(Exception):
    """A non-retryable integration failure."""


def call_with_retry(endpoint_cfg: dict, transport) -> dict:
    """Call an endpoint, retrying transient failures up to the configured limit."""
    url = endpoint_cfg["url"]
    timeout_ms = endpoint_cfg["timeout_ms"]
    retry_count = max(0, endpoint_cfg["retry"])

    attempts = 0

    while attempts < retry_count + 1:
        attempts += 1
        try:
            result = transport(url, timeout_ms)
            return {
                "ok": True,
                "attempts": attempts,
                "result": result,
                "error": None,
            }
        except PermanentError as exc:
            return {
                "ok": False,
                "attempts": attempts,
                "result": None,
                "error": {
                    "type": "permanent",
                    "message": str(exc),
                },
            }
        except TransientError as exc:
            if attempts >= retry_count + 1:
                return {
                    "ok": False,
                    "attempts": attempts,
                    "result": None,
                    "error": {
                        "type": "transient",
                        "message": str(exc),
                    },
                }

    raise RuntimeError("retry loop exited without a result")
